∀ {pattern : Finset RealizationBoundaries.Prime → Set RealizationBoundaries.Prime}
  {supported : ∀ (F : Finset RealizationBoundaries.Prime), pattern F ⊆ ↑F}
  {compatible : ∀ (F G : Finset RealizationBoundaries.Prime), F ⊆ G → pattern F = pattern G ∩ ↑F}
  {pattern_1 : Finset RealizationBoundaries.Prime → Set RealizationBoundaries.Prime}
  {supported_1 : ∀ (F : Finset RealizationBoundaries.Prime), pattern_1 F ⊆ ↑F}
  {compatible_1 : ∀ (F G : Finset RealizationBoundaries.Prime), F ⊆ G → pattern_1 F = pattern_1 G ∩ ↑F},
  { pattern := pattern, supported := supported, compatible := compatible } =
      { pattern := pattern_1, supported := supported_1, compatible := compatible_1 } →
    pattern = pattern_1

∀ {a X : ℕ → Bool} {test answer : ℕ → ℕ} {test_computable : RealizationBoundaries.OracleComputable X test}
  {answer_computable : RealizationBoundaries.OracleComputable X answer}
  {terminates : ∀ (n : ℕ), ∃ t, test (Nat.pair n t) = 0}
  {correct : ∀ (n t : ℕ), test (Nat.pair n t) = 0 → answer (Nat.pair n t) = if a n = true then 1 else 0}
  {test_1 answer_1 : ℕ → ℕ} {test_computable_1 : RealizationBoundaries.OracleComputable X test_1}
  {answer_computable_1 : RealizationBoundaries.OracleComputable X answer_1}
  {terminates_1 : ∀ (n : ℕ), ∃ t, test_1 (Nat.pair n t) = 0}
  {correct_1 : ∀ (n t : ℕ), test_1 (Nat.pair n t) = 0 → answer_1 (Nat.pair n t) = if a n = true then 1 else 0},
  { test := test, answer := answer, test_computable := test_computable, answer_computable := answer_computable,
        terminates := terminates, correct := correct } =
      { test := test_1, answer := answer_1, test_computable := test_computable_1,
        answer_computable := answer_computable_1, terminates := terminates_1, correct := correct_1 } →
    test = test_1 ∧ answer = answer_1

∀ {H : Type u_1} {inst : AddGroup H} {size : ℕ} {names : Fin size ≃ H} {zero : Fin size}
  {add : Fin size → Fin size → Fin size} {zero_spec : names zero = 0}
  {add_spec : ∀ (i j : Fin size), names (add i j) = names i + names j}
  {add_computable : Computable fun k => add k.1 k.2} {size_1 : ℕ} {names_1 : Fin size_1 ≃ H} {zero_1 : Fin size_1}
  {add_1 : Fin size_1 → Fin size_1 → Fin size_1} {zero_spec_1 : names_1 zero_1 = 0}
  {add_spec_1 : ∀ (i j : Fin size_1), names_1 (add_1 i j) = names_1 i + names_1 j}
  {add_computable_1 : Computable fun k => add_1 k.1 k.2},
  { size := size, names := names, zero := zero, add := add, zero_spec := zero_spec, add_spec := add_spec,
        add_computable := add_computable } =
      { size := size_1, names := names_1, zero := zero_1, add := add_1, zero_spec := zero_spec_1,
        add_spec := add_spec_1, add_computable := add_computable_1 } →
    size = size_1 ∧ names ≍ names_1 ∧ zero ≍ zero_1 ∧ add ≍ add_1

