∀ {X : ℕ → Bool} {H : Type u_1} {inst : AddGroup H} {names : ℕ ≃ H} {zero : ℕ} {add : ℕ → ℕ → ℕ}
  {zero_spec : names zero = 0} {add_spec : ∀ (i j : ℕ), names (add i j) = names i + names j}
  {add_computable : RealizationBoundaries.OracleComputable X fun k => add (Nat.unpair k).1 (Nat.unpair k).2}
  {names_1 : ℕ ≃ H} {zero_1 : ℕ} {add_1 : ℕ → ℕ → ℕ} {zero_spec_1 : names_1 zero_1 = 0}
  {add_spec_1 : ∀ (i j : ℕ), names_1 (add_1 i j) = names_1 i + names_1 j}
  {add_computable_1 : RealizationBoundaries.OracleComputable X fun k => add_1 (Nat.unpair k).1 (Nat.unpair k).2},
  { names := names, zero := zero, add := add, zero_spec := zero_spec, add_spec := add_spec,
        add_computable := add_computable } =
      { names := names_1, zero := zero_1, add := add_1, zero_spec := zero_spec_1, add_spec := add_spec_1,
        add_computable := add_computable_1 } →
    names = names_1 ∧ zero = zero_1 ∧ add = add_1

∀ {X : ℕ → Bool} {H : Type u_1} {inst : AddGroup H} {names : ℕ → H} {names_surjective : Function.Surjective names}
  {zero : ℕ} {add equal : ℕ → ℕ → ℕ} {zero_spec : names zero = 0}
  {add_spec : ∀ (i j : ℕ), names (add i j) = names i + names j}
  {equal_spec : ∀ (i j : ℕ), equal i j = 0 ↔ names i = names j}
  {add_computable : RealizationBoundaries.OracleComputable X fun k => add (Nat.unpair k).1 (Nat.unpair k).2}
  {equal_computable : RealizationBoundaries.OracleComputable X fun k => equal (Nat.unpair k).1 (Nat.unpair k).2}
  {names_1 : ℕ → H} {names_surjective_1 : Function.Surjective names_1} {zero_1 : ℕ} {add_1 equal_1 : ℕ → ℕ → ℕ}
  {zero_spec_1 : names_1 zero_1 = 0} {add_spec_1 : ∀ (i j : ℕ), names_1 (add_1 i j) = names_1 i + names_1 j}
  {equal_spec_1 : ∀ (i j : ℕ), equal_1 i j = 0 ↔ names_1 i = names_1 j}
  {add_computable_1 : RealizationBoundaries.OracleComputable X fun k => add_1 (Nat.unpair k).1 (Nat.unpair k).2}
  {equal_computable_1 : RealizationBoundaries.OracleComputable X fun k => equal_1 (Nat.unpair k).1 (Nat.unpair k).2},
  { names := names, names_surjective := names_surjective, zero := zero, add := add, equal := equal,
        zero_spec := zero_spec, add_spec := add_spec, equal_spec := equal_spec, add_computable := add_computable,
        equal_computable := equal_computable } =
      { names := names_1, names_surjective := names_surjective_1, zero := zero_1, add := add_1, equal := equal_1,
        zero_spec := zero_spec_1, add_spec := add_spec_1, equal_spec := equal_spec_1,
        add_computable := add_computable_1, equal_computable := equal_computable_1 } →
    names = names_1 ∧ zero = zero_1 ∧ add = add_1 ∧ equal = equal_1

