∀ {α : Type u_1} (test : α → Bool × List RealizationBoundaries.Prime) (x_1 : α) (xs : List α),
  RealizationBoundaries.countedFindRootTrace test (x_1 :: xs) =
    if (test x_1).1 = true then ((some x_1, (test x_1).2), 1)
    else
      have tail := RealizationBoundaries.countedFindRootTrace test xs;
      ((tail.1.1, (test x_1).2 ++ tail.1.2), tail.2 + 1)

∀ {α : Type u_1} (test : α → Bool × List RealizationBoundaries.Prime) (x : List α),
  RealizationBoundaries.countedFindRootTrace test x =
    match x with
    | [] => ((none, []), 0)
    | x :: xs =>
      have q := test x;
      if q.1 = true then ((some x, q.2), 1)
      else
        have tail := RealizationBoundaries.countedFindRootTrace test xs;
        ((tail.1.1, q.2 ++ tail.1.2), tail.2 + 1)

