∀ {α : Type u_1} (test : α → Bool × List RealizationBoundaries.Prime) (x_1 : α) (xs : List α),
  RealizationBoundaries.findRootTrace test (x_1 :: xs) =
    if (test x_1).1 = true then (some x_1, (test x_1).2)
    else
      have tail := RealizationBoundaries.findRootTrace test xs;
      (tail.1, (test x_1).2 ++ tail.2)

∀ {α : Type u_1} (test : α → Bool × List RealizationBoundaries.Prime) (x : List α),
  RealizationBoundaries.findRootTrace test x =
    match x with
    | [] => (none, [])
    | x :: xs =>
      have q := test x;
      if q.1 = true then (some x, q.2)
      else
        have tail := RealizationBoundaries.findRootTrace test xs;
        (tail.1, q.2 ++ tail.2)

