∀ (a : RealizationBoundaries.Prime → Bool) (r : ℚ) (d : List ℕ) (m n : ℕ),
  RealizationBoundaries.tracedRootCorrectionStep a r d m n =
    if h : Nat.Prime n then
      have q := RealizationBoundaries.tracedRootCorrectionValue a r d m ⟨n, h⟩;
      (ZMod.val q.1, q.2)
    else (0, [])

∀ (a : RealizationBoundaries.Prime → Bool) (r : ℚ) (d : List ℕ) (m n : ℕ),
  RealizationBoundaries.tracedRootObstructs a r d m n =
    if h : Nat.Prime n then
      if n ∣ m then
        have q := RealizationBoundaries.tracedOracleSection a r ⟨n, h⟩;
        (decide (q.1 + RealizationBoundaries.finiteCodeValue d ⟨n, h⟩ ≠ 0), q.2)
      else (false, [])
    else (false, [])
